"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["52448"],{58964(e){e.exports=JSON.parse('{"id":"FIN-1443","slug":"special-purpose-acquisition-company","term":"Special Purpose Acquisition Company (SPAC)","also_known_as":["SPAC"],"difficulty":"Advanced","definition":"A special purpose acquisition company (SPAC) is a publicly listed company created with no operations of its own, which raises money from investors in a stock market listing in order to acquire a private company, taking it public.","explanation":["SPACs are often called blank-cheque companies. A sponsor forms the SPAC and lists it on a stock exchange, raising money that is held in a trust account. The SPAC then has a limited time, often around two years, to find a private company to merge with. If it fails, the money is returned to investors.","When a target is found, the merger, often called a de-SPAC transaction, takes the private company public without a traditional initial public offering. SPAC shareholders can usually choose to redeem their shares for cash if they do not like the deal.","For example, a SPAC might raise 300,000,000, then merge with a private electric vehicle company, which becomes a listed company.","SPACs boomed in the United States in 2020 and 2021. Supporters argue they offer a faster route to listing. Critics point to high costs, generous rewards for sponsors that dilute other shareholders, optimistic projections and poor average share price performance after mergers. Regulators have since tightened disclosure rules."],"note":"","total":1725,"prev":{"slug":"special-drawing-rights","term":"Special Drawing Rights"},"next":{"slug":"special-purpose-vehicle","term":"Special Purpose Vehicle (SPV)"}}')}}]);